# Scheduled Export Feature Design

## Architecture Overview

```
┌─────────────────────────────────────────────────────────────┐
│ Customer UI (NestJS web service)                             │
│ - Schedule export endpoint (validates, stores in Aurora)     │
│ - Download link endpoint (pre-signed S3 URL, 24h expiry)     │
└────────────────┬────────────────────────────────────────────┘
                 │
                 ▼
        ┌────────────────┐
        │ Aurora Writer  │
        │ (existing)     │
        └────────────────┘
                 │
    ┌────────────┴────────────────┐
    │                             │
    ▼                             ▼
┌──────────────────┐      ┌──────────────────┐
│ SQS Queue        │      │ Aurora Reader    │
│ (export jobs)    │      │ (existing)       │
└──────────────────┘      └──────────────────┘
    │
    ▼
┌──────────────────────────────────────────┐
│ ECS Fargate Worker (dedicated export)    │
│ - Polls SQS (1 task, 0.5 vCPU, 1 GB RAM) │
│ - Streams rows from Aurora reader        │
│ - Writes to S3 in chunks                 │
│ - Sends SES email with download link     │
└──────────────────────────────────────────┘
    │
    ▼
┌──────────────────┐
│ S3 (eu-central-1)│
│ (existing)       │
└──────────────────┘
```

## Implementation Details

### 1. Database Schema (Aurora)

```sql
CREATE TABLE scheduled_exports (
  id UUID PRIMARY KEY,
  customer_id UUID NOT NULL,
  name VARCHAR(255) NOT NULL,
  format VARCHAR(10) NOT NULL, -- 'csv' or 'xlsx'
  schedule_cron VARCHAR(100) NOT NULL, -- e.g., '0 2 * * 1' (Mon 2am UTC)
  filters JSONB, -- optional: date range, department, etc.
  created_at TIMESTAMP DEFAULT NOW(),
  updated_at TIMESTAMP DEFAULT NOW(),
  is_active BOOLEAN DEFAULT TRUE,
  FOREIGN KEY (customer_id) REFERENCES customers(id)
);

CREATE TABLE export_jobs (
  id UUID PRIMARY KEY,
  scheduled_export_id UUID NOT NULL,
  status VARCHAR(50) DEFAULT 'pending', -- pending, processing, completed, failed
  started_at TIMESTAMP,
  completed_at TIMESTAMP,
  row_count INT,
  s3_key VARCHAR(500),
  error_message TEXT,
  created_at TIMESTAMP DEFAULT NOW(),
  FOREIGN KEY (scheduled_export_id) REFERENCES scheduled_exports(id)
);

CREATE INDEX idx_export_jobs_status ON export_jobs(status, created_at DESC);
CREATE INDEX idx_scheduled_exports_customer ON scheduled_exports(customer_id);
```

### 2. Job Scheduling (NestJS)

Use a **cron job in the web service** (not a separate service) that runs every minute:

```typescript
// export-scheduler.service.ts
@Injectable()
export class ExportSchedulerService {
  constructor(
    private db: Database,
    private sqs: SQSClient,
  ) {}

  @Cron('* * * * *') // Every minute
  async triggerScheduledExports() {
    const now = new Date();

    // Find exports due in the next 2 minutes (idempotency window)
    const dueSoon = await this.db.query(`
      SELECT id, scheduled_export_id, customer_id, format, filters
      FROM scheduled_exports
      WHERE is_active = TRUE
        AND (last_triggered_at IS NULL 
             OR last_triggered_at < NOW() - INTERVAL '1 day')
        AND cron_matches(schedule_cron, $1)
      LIMIT 100
    `, [now]);

    for (const export of dueSoon) {
      const job = {
        id: uuidv4(),
        scheduled_export_id: export.id,
        customer_id: export.customer_id,
        format: export.format,
        filters: export.filters,
      };

      await this.sqs.send(new SendMessageCommand({
        QueueUrl: process.env.EXPORT_QUEUE_URL,
        MessageBody: JSON.stringify(job),
        MessageDeduplicationId: `${export.id}-${now.toISOString()}`,
        MessageGroupId: export.customer_id, // FIFO queue
      }));

      await this.db.query(
        'UPDATE scheduled_exports SET last_triggered_at = NOW() WHERE id = $1',
        [export.id]
      );
    }
  }
}
```

**Why in the web service?** Cron jobs are lightweight (runs 1 query + ~10 SQS sends per minute). No separate infrastructure needed.

### 3. Export Worker (Dedicated ECS Task)

```typescript
// export-worker.service.ts
@Injectable()
export class ExportWorkerService {
  constructor(
    private db: Database,
    private s3: S3Client,
    private sqs: SQSClient,
    private ses: SESClient,
  ) {}

  async processExportJob(job: ExportJob) {
    const jobRecord = await this.db.query(
      'INSERT INTO export_jobs (id, scheduled_export_id, status) VALUES ($1, $2, $3) RETURNING *',
      [job.id, job.scheduled_export_id, 'processing']
    );

    try {
      const s3Key = `exports/${job.customer_id}/${job.id}.${job.format === 'csv' ? 'csv' : 'xlsx'}`;

      if (job.format === 'csv') {
        await this.streamToCSV(job, s3Key);
      } else {
        await this.streamToXLSX(job, s3Key);
      }

      // Update job status
      await this.db.query(
        'UPDATE export_jobs SET status = $1, s3_key = $2, row_count = $3, completed_at = NOW() WHERE id = $4',
        ['completed', s3Key, jobRecord.row_count, job.id]
      );

      // Send email with pre-signed URL
      await this.sendDownloadEmail(job.customer_id, s3Key);

    } catch (error) {
      await this.db.query(
        'UPDATE export_jobs SET status = $1, error_message = $2 WHERE id = $3',
        ['failed', error.message, job.id]
      );
      // Log to CloudWatch for alerting
    }
  }

  private async streamToCSV(job: ExportJob, s3Key: string) {
    const multipartUpload = await this.s3.send(new CreateMultipartUploadCommand({
      Bucket: process.env.EXPORT_BUCKET,
      Key: s3Key,
    }));

    const parts = [];
    let partNumber = 1;
    let rowCount = 0;
    let csvBuffer = '';
    const CHUNK_SIZE = 5 * 1024 * 1024; // 5 MB chunks

    // Stream from Aurora reader with cursor
    const cursor = await this.db.query(
      'SELECT * FROM payroll_records WHERE customer_id = $1 AND created_at > NOW() - INTERVAL \'1 year\' ORDER BY id',
      [job.customer_id],
      { batchSize: 10000 } // Fetch 10k rows at a time
    );

    for await (const row of cursor) {
      if (rowCount === 0) {
        csvBuffer = Object.keys(row).join(',') + '\n'; // Header
      }
      csvBuffer += Object.values(row).map(v => `"${v}"`).join(',') + '\n';
      rowCount++;

      if (Buffer.byteLength(csvBuffer) > CHUNK_SIZE) {
        const part = await this.s3.send(new UploadPartCommand({
          Bucket: process.env.EXPORT_BUCKET,
          Key: s3Key,
          PartNumber: partNumber,
          UploadId: multipartUpload.UploadId,
          Body: csvBuffer,
        }));
        parts.push({ ETag: part.ETag, PartNumber: partNumber });
        csvBuffer = '';
        partNumber++;
      }
    }

    // Upload final chunk
    if (csvBuffer.length > 0) {
      const part = await this.s3.send(new UploadPartCommand({
        Bucket: process.env.EXPORT_BUCKET,
        Key: s3Key,
        PartNumber: partNumber,
        UploadId: multipartUpload.UploadId,
        Body: csvBuffer,
      }));
      parts.push({ ETag: part.ETag, PartNumber: partNumber });
    }

    await this.s3.send(new CompleteMultipartUploadCommand({
      Bucket: process.env.EXPORT_BUCKET,
      Key: s3Key,
      UploadId: multipartUpload.UploadId,
      MultipartUpload: { Parts: parts },
    }));

    return rowCount;
  }

  private async sendDownloadEmail(customerId: string, s3Key: string) {
    const presignedUrl = await getSignedUrl(
      this.s3,
      new GetObjectCommand({
        Bucket: process.env.EXPORT_BUCKET,
        Key: s3Key,
      }),
      { expiresIn: 86400 } // 24 hours
    );

    const customer = await this.db.query('SELECT email FROM customers WHERE id = $1', [customerId]);

    await this.ses.send(new SendEmailCommand({
      Source: 'exports@company.nl',
      Destination: { ToAddresses: [customer.email] },
      Message: {
        Subject: { Data: 'Your payroll export is ready' },
        Body: {
          Html: { Data: `<a href="${presignedUrl}">Download export</a> (expires in 24h)` },
        },
      },
    }));
  }
}
```

### 4. Worker ECS Task Configuration

```yaml
# docker-compose.yml (worker service)
services:
  export-worker:
    image: myapp:latest
    environment:
      - NODE_ENV=production
      - WORKER_MODE=export
      - EXPORT_QUEUE_URL=${EXPORT_QUEUE_URL}
    resources:
      cpus: '0.5'
      memory: '1024'
    logging:
      awslogs-group: /ecs/export-worker
      awslogs-region: eu-central-1
```

**ECS Task Definition:**
- **CPU:** 0.5 vCPU (512 CPU units)
- **Memory:** 1 GB
- **Count:** 1 task (always running)
- **Scaling:** Manual (no auto-scaling needed at this volume)

